EMSS_SUPPORT = 'i_iht_automation@internal.nsn.com'
LOG_DIR = os.getenv('EMSSIM_LOG_DIR', '/var/log/emssim')


class ta_emss(EmssimProcessStarter, AlarmManager, eNBManager, CellTraceManager, FileManager,
              ObjectManager, SshManager, PlanManager, PMManager, ProxyManager, SDLManager, XtermManager):
    """
    EMSsim interface for Python based frameworks
    """
    ROBOT_LIBRARY_SCOPE = 'TEST SUITE'  # 'TEST CASE' 'GLOBAL'
    ROBOT_LISTENER_API_VERSION = 2
    CLOUD_ENB_IP_ENB_ID = {'10.0.1.2': 1,
                           '10.0.1.4': 2,
                           '10.0.1.6': 3,
                           '10.0.1.8': 4
                           }

    ta_emss_instances = {}
    auto_connected_enbs = []
    emssim_conf = {}
    last_bts_id = None
    last_instance = None
    suite_loggers = []
    test_loggers = []
    suite_name = None
    test_name = None
    debug_om = int(os.environ['DEBUG_OM']) if 'DEBUG_OM' in os.environ and os.environ['DEBUG_OM'].isdigit() else None
    debug_om_inst = int(os.environ['DEBUG_OM_INST']) if 'DEBUG_OM_INST' in os.environ and os.environ['DEBUG_OM_INST'].isdigit() else None
    log_om = int(os.environ['LOG_OM']) if 'LOG_OM' in os.environ and os.environ['LOG_OM'].isdigit() else None
    log_fd = None
    log_dir = LOG_DIR
    gi_num = 0

    @classmethod
    def _start_log(cls, log_dir=None):
        if not cls.debug_om:
            return

        if cls.log_fd is not None:
            return

        log_dir = log_dir if log_dir is not None else LOG_DIR
        now = datetime.datetime.now()
        log_file = "{}/".format(log_dir) + "ta_emss-" + now.strftime("%Y%m%d_%H%M%S") + ".log"

        try:
            cls.log_dir = log_dir
            cls.log_fd = open(log_file, "a", 1)
            cls.log_fd.write(now.strftime("\n%d %H:%M:%S |##:LOG:##\n\n"))
        except Exception as exc:
            print("Logging ta_emss is OFF due to: [%s]" % str(exc))

    @classmethod
    def _inc_gi(cls):
        cls.gi_num += 1

    @classmethod
    def _log(cls, msg):
        if not cls.debug_om:
            return

        now = datetime.datetime.now()
        ms = ".%03d" % (now.microsecond / 1000)
        gi = "%06d" % (cls.gi_num)
        msg = now.strftime("%d %H:%M:%S") + ms + " | " + gi + " | " + msg + "\n"
        try:
            cls.log_fd.write(msg)
        except Exception:
            print(msg)

    @classmethod
    def _get_emss_name(cls, name, host, port):
        return "%s_%s_%s" % (name, str(host), str(port))

    @classmethod
    def _get_user(cls, instance_id):
        return "flexi" + str(instance_id)

    @classmethod
    def _add_instance(cls, instance_id, emss_name, ref, alias):
        cls._log("*** add_instance: instance_id={}, name={}, ref={}, alias={}".format(instance_id, emss_name, ref, alias))
        if alias:
            cls.ta_emss_instances[alias] = ref
        else:
            to_del = []
            for (name, emss_inst) in cls.ta_emss_instances.items():
                if emss_inst.instance_id == instance_id:
                    to_del.append(name)
            for name in to_del:
                cls.ta_emss_instances.pop(name)

            cls.ta_emss_instances[emss_name] = ref

        if cls.debug_om_inst:
            cls._log("########################  INSTANCES  ###############################")
            for (n, i) in cls.ta_emss_instances.items():
                iden = hex(id(i))
                cls._log("NAME(%s): INST=%s, ALIAS=%s, NAME=%s, HOST=%s, PORT=%s, USER=%s, EMSSIM=%s, OM=%s [%s]" %
                         (n, i.instance_id, i.alias, i.emss_name, i.emss_host, i.emss_port, i.user, i.emssim, i.om, iden))
            cls._log("####################################################################")

    @classmethod
    def _start_loggers(cls, robot_log_dir):
        cls._start_suite_loggers(robot_log_dir)
        cls._start_test_loggers(robot_log_dir)

    @classmethod
    def _start_logger(cls, host, port, name, robot_log_dir):
        log_inst = EmssFileLogger(emss_host=host, emss_port=port)
        log_inst.set_filepath(robot_log_dir, name)
        log_inst.start_emss_logging()
        return log_inst

    @classmethod
    def _start_suite_loggers(cls, robot_log_dir):
        if not cls.suite_name:
            return
        if not robot_log_dir:
            return

        for (host, port, log_port) in cls._get_emss_instances_params():
            is_logging = False
            for log_inst in cls.suite_loggers:
                if log_inst.emss_host == host and log_inst.emss_port == log_port:
                    is_logging = True
                    break
            if not is_logging:
                log_inst = cls._start_logger(host, log_port, 'SUITE_' + cls.suite_name, robot_log_dir)
                cls.suite_loggers.append(log_inst)

    @classmethod
    def _start_test_loggers(cls, robot_log_dir):
        if not cls.test_name:
            return
        if not robot_log_dir:
            return

        for (host, port, log_port) in cls._get_emss_instances_params():
            is_logging = False
            for log_inst in cls.test_loggers:
                if log_inst.emss_host == host and log_inst.emss_port == log_port:
                    is_logging = True
                    break
            if not is_logging:
                log_inst = cls._start_logger(host, log_port, 'TEST_' + cls.test_name, robot_log_dir)
                cls.test_loggers.append(log_inst)

    @classmethod
    def _stop_test_loggers(cls):
        for log_ins in cls.test_loggers:
            log_ins.stop_emss_logging()
        cls.test_loggers = []

    @classmethod
    def _stop_suite_loggers(cls):
        for log_ins in cls.suite_loggers:
            log_ins.stop_emss_logging()
        cls.suite_loggers = []

    @classmethod
    def _get_instance_by_name(cls, name):
        if cls.debug_om_inst:
            cls._log("====================================================================")
            cls._log("==> REQ_NAME=%s" % (name))
            for (n, i) in cls.ta_emss_instances.items():
                iden = hex(id(i))
                cls._log("NAME(%s): INST=%s, ALIAS=%s, HOST=%s, PORT=%s, USER=%s, EMSSIM=%s, OM=%s [%s]" %
                         (n, i.instance_id, i.alias, i.emss_host, i.emss_port, i.user, i.emssim, i.om, iden))
            cls._log("====================================================================")

        if name in cls.ta_emss_instances:
            return cls.ta_emss_instances[name]

        return None

    @classmethod
    def _get_instance_by_alias(cls, alias):
        if cls.debug_om_inst:
            cls._log("====================================================================")
            cls._log("==> REQ_ALIAS=%s" % (alias))
            for (n, i) in cls.ta_emss_instances.items():
                iden = hex(id(i))
                cls._log("NAME(%s): INST=%s, ALIAS=%s, HOST=%s, PORT=%s, USER=%s, EMSSIM=%s, OM=%s [%s]" %
                         (n, i.instance_id, i.alias, i.emss_host, i.emss_port, i.user, i.emssim, i.om, iden))
            cls._log("====================================================================")

        if alias in cls.ta_emss_instances:
            return cls.ta_emss_instances[alias]

        for (emss_name, emss_inst) in cls.ta_emss_instances.items():
            if emss_inst.alias == alias:
                return emss_inst

        return None

    @classmethod
    def _get_instance_by_instance_id(cls, instance_id):
        if cls.debug_om_inst:
            cls._log("====================================================================")
            cls._log("==> REQ_INSTANCE_ID=%s" % (instance_id))
            for (name, i) in cls.ta_emss_instances.items():
                iden = hex(id(i))
                cls._log("INST(%s): NAME=%s, ALIAS=%s, HOST=%s, PORT=%s, USER=%s, EMSSIM=%s, OM=%s [%s]" %
                         (i.instance_id, name, i.alias, i.emss_host, i.emss_port, i.user, i.emssim, i.om, iden))
            cls._log("====================================================================")

        for emss_inst in cls.ta_emss_instances.values():
            if emss_inst.instance_id == instance_id:
                return emss_inst
        return None

    @classmethod
    def _get_all_enb_ids_with_ta_emss_instances(cls, only_discovered=False):
        cls._log_existing_ta_emss_instances()
        enb_ids = []
        if only_discovered is True:
            for instance in list(cls.ta_emss_instances.values()):
                if instance.om is not None:
                    enb_id = instance.om.get_enb_id()
                    enb_ids.append(enb_id)
                else:
                    cls._log('Creating instance dynamically, will work only with single eNB')
                    instance.setup_emss(enb_id=instance.instance_id)
                    enb_id = instance.om.get_enb_id()
                    enb_ids.append(enb_id)
        else:
            for instance in list(cls.ta_emss_instances.values()):
                enb_ids.append(instance.instance_id)
        return enb_ids

    @classmethod
    def _get_all_instances(cls):
        cls._log_existing_ta_emss_instances()
        return list(cls.ta_emss_instances.values())

    @classmethod
    def _log_existing_ta_emss_instances(cls):
        if cls.debug_om_inst:
            cls._log("====================================================================")
            for (name, i) in cls.ta_emss_instances.items():
                cls._log("INST(%s): NAME=%s, HOST=%s, PORT=%s, USER=%s, EMSSIM=%s, OM=%s" %
                         (i.instance_id, name, i.emss_host, i.emss_port, i.user, i.emssim, i.om))

            cls._log("====================================================================")

    @classmethod
    def _get_emss_instances_params(cls):
        ret_list = []
        for emss_inst in cls.ta_emss_instances.values():
            if emss_inst.emss_host is not None and emss_inst.emss_port is not None and emss_inst.emssim is not None:
                log_port = emss_inst.server_port if emss_inst.server_port is not None else emss_inst.emss_port + 3000
                ret_list.append((emss_inst.emss_host, emss_inst.emss_port, log_port))
        return ret_list

    @classmethod
    def _get_host_from_emssim_config(cls):
        fpip_key = 'FLEXI_PROXY_IP'
        fpip = None
        try:
            fpip = cls.emssim_conf[fpip_key]
        except KeyError:
            try:
                with open('/etc/emssim.conf') as cfg_file:
                    for line in cfg_file:
                        ltab = line.split()
                        if ltab and ltab[0] == 'flexi_proxy' and ltab[1] == '=':
                            fpip = ltab[2].split(':')[0]
                            cls.emssim_conf[fpip_key] = fpip
            except Exception as exc:
                cls._log("Cannot get HOST IP from emssim default config: %s" % str(exc))
                cls.emssim_conf[fpip_key] = None
        return fpip

    @classmethod
    def _get_primary_oam_ip_from_emssim_config(cls):
        ds_key = 'DATA_SERVER'
        ds = None
        try:
            ds = cls.emssim_conf[ds_key]
        except KeyError:
            try:
                with open('/etc/emssim.conf') as cfg_file:
                    for line in cfg_file:
                        ltab = line.split()
                        if ltab and ltab[0] == 'data_server' and ltab[1] == '=':
                            ds = ltab[2]
                            cls.emssim_conf[ds_key] = ds
            except Exception as exc:
                cls._log("Cannot get Primary OAM IP from emssim default config: %s" % str(exc))
        return ds

    @classmethod
    def get_aliases(cls):
        return list(ta_emss.ta_emss_instances.keys())

    def __new__(cls, *args, **kwargs):
        """
        ta_emss library construction

        :param name: name of the emssim session
        :param host: IP address of emssim session
        :param port: TCP port of emssim session

        Note: you can get host/port directly from EMSsim session by executing the command 'json_svr'
        ==================================================================
        Library  ta_emss   name=emss1  host=10.0.1.1  port=4001
        ==================================================================
        """
        name = kwargs.get('name', 'emss')
        host = kwargs.get('host', None)
        port = int(kwargs['port']) if 'port' in kwargs and kwargs['port'] is not None else None
        user = kwargs.get('user', None)
        enb_id = int(kwargs['enb_id']) if 'enb_id' in kwargs and kwargs['enb_id'] is not None else None
        bts_id = int(kwargs['bts_id']) if 'bts_id' in kwargs and kwargs['bts_id'] is not None else enb_id
        alias = kwargs.get('alias', None)
        log_dir = kwargs.get('log_dir', LOG_DIR)
        instance_id = bts_id

        cls._start_log(log_dir=log_dir)

        if host is None:
            host = cls._get_host_from_emssim_config()

        if instance_id is None:
            if port is not None and port > 4000:
                instance_id = port - 4000
            else:
                instance_id = 1

        if port is None:
            port = 4000 + instance_id

        cls._log("__NEW__=(id=%s, a=%s, h=%s, p=%s) last_id=%s" % (instance_id, alias, host, port, cls.last_bts_id))

        emss_name = cls._get_emss_name(name, host, port)

        emss_inst = cls._get_instance_by_name(emss_name)
        if emss_inst is None:
            emss_inst = super(ta_emss, cls).__new__(cls)
            kwargs.pop('host', None)
            kwargs.pop('port', None)
            kwargs.pop('instance_id', None)
            kwargs.pop('emss_name', None)
            kwargs.pop('user', None)
            kwargs.pop('alias', None)
            emss_inst._set_new_instance(host, port, instance_id, emss_name, user, alias, **kwargs)
            cls._add_instance(instance_id, emss_name, emss_inst, alias)
            cls._log("NEW=(id=%s, a=%s, n=%s, h=%s, p=%s) last_id=%s" %
                     (emss_inst.instance_id, emss_inst.alias, emss_inst.emss_name, emss_inst.emss_host, emss_inst.emss_port, cls.last_bts_id))
        else:
            cls._log("GOT=(id=%s, a=%s, n=%s, h=%s, p=%s) last_id=%s" %
                     (emss_inst.instance_id, emss_inst.alias, emss_inst.emss_name, emss_inst.emss_host, emss_inst.emss_port, cls.last_bts_id))

        return emss_inst

    def __init__(self, *args, **kwargs):
        super(ta_emss, self).__init__()
        if self._is_dry_run():
            return

        self.robot_log_dir = get_robot_output_dir()
        if self.robot_log_dir:
            self.ROBOT_LIBRARY_LISTENER = self

        if self.run_setup and self.emss_host and self.emss_port:
            self.run_setup = False

            if 'wait_connected' not in kwargs:
                kwargs['wait_connected'] = True

            if 'wait_discovered' not in kwargs:
                kwargs['wait_discovered'] = True

            self.setup_emss(**kwargs)
        if self._opt_bool(kwargs.get('auto_connect', False)) is True:
            self.auto_create_emssim_for_connected_enbs()

    def _set_new_instance(self, host, port, instance_id, emss_name, user, alias, **kwargs):
        self.emss_host = host
        self.emss_port = port
        self.instance_id = instance_id
        self.emss_name = emss_name
        self.alias = alias
        self.setup_args = {}
        self.server_port = kwargs['server_port'] if 'server_port' in kwargs else None
        self.logging = kwargs['logging'] if 'logging' in kwargs else True
        self.timeout = kwargs['timeout'] if 'timeout' in kwargs else 240
        self.bts_timeout = kwargs['bts_timeout'] if 'bts_timeout' in kwargs else 360
        self.wait_tcp_connected = kwargs['wait_tcp_connected'] if 'wait_tcp_connected' in kwargs else False
        self.wait_connected = kwargs['wait_connected'] if 'wait_connected' in kwargs else True
        self.wait_discovered = kwargs['wait_discovered'] if 'wait_discovered' in kwargs else True
        self.debug_fbox = kwargs['debug_fbox'] if 'debug_fbox' in kwargs else True
        self.reg_user = kwargs['reg_user'] if 'reg_user' in kwargs else None
        self.reg_password = kwargs['reg_password'] if 'reg_password' in kwargs else None
        self.tls = kwargs['tls'] if 'tls' in kwargs else False
        self.pnp = kwargs['pnp'] if 'pnp' in kwargs else False
        self.ac = kwargs['ac'] if 'ac' in kwargs else False
        self.certm = kwargs['certm'] if 'certm' in kwargs else False
        self.ne3s = kwargs['ne3s'] if 'ne3s' in kwargs else True
        self.manager_id = kwargs['manager_id'] if 'manager_id' in kwargs else None
        self.oam_ip = kwargs['oam_ip'] if 'oam_ip' in kwargs else None
        self.bts_ip = kwargs['bts_ip'] if 'bts_ip' in kwargs else None
        self.start_params = kwargs['start_params'] if 'start_params' in kwargs else {}
        self.run_apps = kwargs['run_apps'] if 'run_apps' in kwargs else True
        self.run_setup = kwargs['run_setup'] if 'run_setup' in kwargs else True

        self.emss_support = EMSS_SUPPORT
        self.emssim = None
        self.om = None
        self.already_checked_rtpm_counters = []
        self.rtpm_interval = {'start': None,
                              'stop': None,
                              'rtpm_activate': None}
        self.cmd_attr_attributes_details = {}
        self.host_local = True
        self.is_logging = False
        self.is_ute = self._get_ute()
        self.check_emss = True
        self.last_sdl = None
        self.user = None
        self.pdl_mode = None
        self.use_admin = None
        self.om_type = None
        self._set_user(instance_id, user)
        self._set_pdl_mode()
        self._set_use_admin()
        self._set_om_type()
        ta_emss._log("New EMSsim instance: %s" % self.emss_name)
        self._report_om_pdl_mode()

    def _clear_cache(self):
        self.cmd_attr_attributes_details = {}

    def _opt_int(self, val):
        if val is None or isinstance(val, int):
            return val
        return int(self._opt_eval(val))

    def _opt_int_or_list(self, val):
        if val is None or isinstance(val, int) or isinstance(val, list):
            return val
        e_val = self._opt_eval(val)
        if isinstance(e_val, list):
            return e_val
        return int(e_val)

    def _opt_bool(self, val):
        try:
            return str(val).lower().strip() == "true"
        except Exception:
            return False

    def _opt_dict(self, val):
        if val is None or isinstance(val, dict):
            return val
        return self._opt_eval(val)

    def _opt_dict_or_list(self, val):
        if val is None or isinstance(val, dict) or isinstance(val, list):
            return val
        return self._opt_eval(val)

    def _opt_eval(self, val):
        if not isinstance(val, six.string_types):
            return val
        return ast.literal_eval(val.strip())

    def _opt_id(self, enb_id, bts_id):
        if bts_id is None:
            bts_id = enb_id
        return self._opt_int(bts_id)

    def _set_user(self, instance_id, user=None):
        if user:
            self.user = user
        else:
            self.user = self._get_user(instance_id)

    def _get_ute(self):
        ret = False
        try:
            home = os.environ['HOME'] if 'HOME' in os.environ else None
            user = os.environ['USER'] if 'USER' in os.environ else None
            if home == '/home/ute' or user == 'ute':
                ta_emss._log("UTE detected")
                ret = True
        except Exception as exc:
            ta_emss._log("Cannot detect UTE: {}".format(exc))
        return ret

    def _get_instance(self, instance_id, alias, host=None, port=None, check_emss=True, **kwargs):
        emss_port = int(port) if port is not None else None
        ta_emss._inc_gi()

        inst_id = self._get_instance_id(instance_id, alias, emss_port)

        emss_inst = None

        if alias is not None:
            emss_inst = ta_emss._get_instance_by_alias(alias)

        if emss_inst is None and ta_emss.last_instance is not None and instance_id is None and alias is None and host is None and port is None:
            emss_inst = ta_emss.last_instance

        if emss_inst is None and host is None and port is None and alias is None:
            emss_inst = ta_emss._get_instance_by_instance_id(inst_id)

        if emss_inst is None:
            emss_inst = ta_emss(host=host, port=emss_port, enb_id=inst_id, alias=alias, **kwargs)

        ta_emss._log("REQ=(id=%s, a=%s, h=%s, p=%s) GOT=(id=%s, a=%s, h=%s, p=%s), last_id=%s, from=%s" %
                     (instance_id, alias, host, port, emss_inst.instance_id, emss_inst.alias, emss_inst.emss_host, emss_inst.emss_port,
                      ta_emss.last_bts_id, sys._getframe().f_back.f_code.co_name))

        if alias:
            emss_inst.alias = alias

        if check_emss and emss_inst.check_emss:
            emss_inst._check_emssim()

        ta_emss.last_instance = emss_inst

        return emss_inst

    def _get_instance_id(self, instance_id, alias, port):
        if instance_id is None and alias is None and port is not None and port > 4000:
            instance_id = port - 4000

        if instance_id:
            ta_emss.last_bts_id = int(instance_id)
        else:
            if ta_emss.last_bts_id:
                instance_id = ta_emss.last_bts_id
            else:
                instance_id = self.instance_id
        return int(instance_id)

    def _check_emssim(self):
        if self.emssim:
            if self.emssim.is_running():
                return

            ta_emss._log("[%d] WARNING: RPC and/or Transport is not running. Trying to recover." % self.instance_id)
            try:
                assert self.emssim.check_hb()
            except Exception as exc:
                if not self.host_local:
                    ta_emss._log("[%d] ERROR: EMSsim did not respond to heartbeat, but cannot restart remote EMSsim session (%s)." %
                                 (self.instance_id, str(exc)))
                    raise
                ta_emss._log("EMSsim did not respond to heartbeat. Restart forced (%s)." % str(exc))
                try:
                    self.recover_emss_connection()
                except Exception as exc:
                    ta_emss._log("Cannot restart EMSsim: %s" % str(exc))

    def _get_emssim(self):
        if self.emssim:
            return self.emssim
        ta_emss._log("WARNING: Request for not initialized EMSsim")
        self._run_setup_emss()
        if not self.emssim:
            traceback.print_stack()
        return self.emssim

    def _get_om(self):
        if self.om:
            return self.om
        ta_emss._log("WARNING: Request for not initialized OM")
        self._run_setup_emss()
        if not self.om:
            traceback.print_stack()
        return self.om

    def _assert(self, condition, message, can_fail=False):
        if not can_fail:
            if not condition:
                if self.is_logging:
                    self.logging_stop()
                    self.logging_start()
        assert condition, message

    def _remove_emssim(self):
        if self.emssim:
            self.emssim = None
            devicemanager.remove_device_from_registry(self.emss_name)

    def _is_dry_run(self):
        try:
            current_context = self._get_robot_context()
            if current_context.dry_run:
                self._wa_for_ta_emss_configurator_migration()
                return True
        except Exception:
            pass
        return False

    def _is_robot(self):
        try:
            current_context = self._get_robot_context()
            if current_context is not None:
                return True
        except Exception:
            pass
        return False

    def _get_robot_context(self):
        try:
            from robot.running.context import EXECUTION_CONTEXTS
            return EXECUTION_CONTEXTS.current
        except Exception:
            pass
        return None

    def _auto_discover_available_enbs(self):
        for (enb_ip, enb_id) in ta_emss.CLOUD_ENB_IP_ENB_ID.items():
            if self._ping_ute_cloud_enb_ip(enb_ip) is True:
                ta_emss.auto_connected_enbs.append(enb_id)

    def _ping_ute_cloud_enb_ip(self, host):
        return os.system("ping -c 1 -w 3 {} > /dev/null 2>&1".format(host)) == 0

    def auto_create_emssim_for_connected_enbs(self):
        """
        Pings available UTE CLOUD ENB ips and starts separate emssim instances for each discovered enb
        :return:
        """
        self._auto_discover_available_enbs()
        instances = []
        for enb_id in ta_emss.auto_connected_enbs:
            ta_emss._log("Creating emssim for eNB: {}".format(enb_id))
            instances.append(self._run_setup_emss(bts_id=enb_id))
        return instances

    def get_enb_ids_with_created_emss_instances(self, discovered=True):
        """
        Return list of eNB ids for which emssim is created

        :param discovered: Get only discovered BTSes (default=True)
        :return:
        """
        discovered = self._opt_bool(discovered)
        return ta_emss._get_all_enb_ids_with_ta_emss_instances(only_discovered=discovered)

    def _is_btsmed(self):
        if self.om_type == 'BTSMED':
            return True
        return False

    def _report_om_pdl_mode(self):
        om = 'NETACT'
        if self._is_btsmed():
            om = 'BTSMED'

        ta_emss._log("PDL_MODE: (OM={}) {}".format(om, self.pdl_mode))
        if self._is_config_wa_only():
            ta_emss._log("PDL_MODE: (OM={}) WA only".format(om))
        if self._is_config_admin():
            ta_emss._log("PDL_MODE: (OM={}) ADMIN after failure".format(om))
        if self._is_config_wa():
            ta_emss._log("PDL_MODE: (OM={}) WA after failure".format(om))

    def _is_config_wa_only(self):
        if self.pdl_mode is None or self.pdl_mode == 'WA':
            return True
        return False

    def _is_config_wa(self):
        if self.pdl_mode == 'ADMIN_WA':
            return True
        return False

    def _is_config_admin(self):
        if self.pdl_mode == 'ADMIN' or self.pdl_mode == 'ADMIN_WA':
            return True
        return False

    def _set_pdl_mode(self):
        allowed_modes = ['WA', 'ADMIN', 'ADMIN_WA', 'NETACT']
        pdl_mode = None
        try:
            if self._is_robot() is True:
                from robot.libraries.BuiltIn import BuiltIn
                pdl_mode = BuiltIn().get_variable_value('${PDL_MODE}')
                ta_emss._log("PDL_MODE from ROBOT: {}".format(pdl_mode))
            if pdl_mode is None:
                pdl_mode = os.environ['PDL_MODE']
                ta_emss._log("PDL_MODE from ENV: {}".format(pdl_mode))
        except Exception:
            ta_emss._log("No PDL_MODE variable defined")

        if pdl_mode:
            if pdl_mode in allowed_modes:
                self.pdl_mode = pdl_mode
            else:
                ta_emss._log("Not allowed PDL_MODE: {}".format(pdl_mode))
        else:
            # self.pdl_mode = 'ADMIN'
            # self.pdl_mode = 'WA'
            self.pdl_mode = 'ADMIN_WA'

    def _set_use_admin(self):
        try:
            if self._is_robot() is True:
                from robot.libraries.BuiltIn import BuiltIn
                self.use_admin = BuiltIn().get_variable_value('${USE_ADMIN}')
                ta_emss._log("USE_ADMIN from ROBOT: {}".format(self.use_admin))
            if self.use_admin is None and 'USE_ADMIN' in os.environ and os.environ['USE_ADMIN'].isdigit():
                self.use_admin = int(os.environ['USE_ADMIN'])
                ta_emss._log("USE_ADMIN from ENV: {}".format(self.use_admin))
        except Exception as exc:
            ta_emss._log("Cannot set USE_ADMIN variable: {}".format(exc))

    def _set_om_type(self):
        try:
            if self._is_robot() is True:
                from robot.libraries.BuiltIn import BuiltIn
                self.om_type = BuiltIn().get_variable_value('${OM_TYPE}')
                ta_emss._log("OM_TYPE from ROBOT: {}".format(self.om_type))
            if self.om_type is None:
                self.om_type = os.environ.get('OM_TYPE')
                ta_emss._log("OM_TYPE from ENV: {}".format(self.om_type))
            if self.om_type is None:
                # out, rc = self._run_cmd("PATH=$PATH:/home/ute/robotlte/resources/DevKr enb_check_btsmed_compatibility.sh")
                # if rc == 0:
                #     ta_emss._log("BTSMED compatibility detected. Setting OM_TYPE=BTSMED")
                #     self.om_type = 'BTSMED'
                self.om_type = 'NETACT'
        except Exception:
            ta_emss._log("No OM_TYPE variable defined")

    def _wa_for_ta_emss_configurator_migration(self):
        if self._is_robot() is True:
            from robot.libraries.BuiltIn import BuiltIn
            BuiltIn().set_library_search_order('ta_emss', 'ta_emss_configurator')

    def _wa_for_pdl_validation(self, after_failure=False):
        if self._is_btsmed():
            return
        if after_failure and not self._is_config_wa():
            return
        if not after_failure and not self._is_config_wa_only():
            return
        try:
            # if self._is_robot() is True:
            #     from robot.libraries.BuiltIn import BuiltIn
            #     suite_source = BuiltIn().get_variable_value('${SUITE_SOURCE}')
            #     ta_emss._log("SUITE_SOURCE: {}".format(suite_source))
            #     if "DevKr" in suite_source:
            #         out = self._run("/home/ute/robotlte/resources/DevKr/enb_pdl_validator_upload.sh", timeout=300)
            #         ta_emss._log("PDL VALIDATOR WA output: [{}]".format(out))
            ta_emss._log("PDL WA has obsoleted")
        except Exception as exc:
            ta_emss._log("Cannot apply pdl validation WA: {}".format(exc))

    def _copy_file_to_log_dir(self, file_path):
        if self.robot_log_dir:
            try:
                ta_emss._log("Copy file {} to {}".format(file_path, self.robot_log_dir))
                self._run("cp {} {}".format(file_path, self.robot_log_dir))
            except Exception as exc:
                ta_emss._log("Cannot copy file: {}".format(exc))
    # ---  Robot callbacks  ---

    def _start_suite(self, name, attrs):
        ta_emss.suite_name = name
        ta_emss._start_loggers(self.robot_log_dir)
        self._wa_for_ta_emss_configurator_migration()

    def _start_test(self, name, attrs):
        ta_emss.test_name = name
        ta_emss._start_loggers(self.robot_log_dir)

    def _end_suite(self, name, attrs):
        ta_emss._stop_suite_loggers()
        ta_emss.suite_name = None

    def _end_test(self, name, attrs):
        ta_emss._stop_test_loggers()
        ta_emss.test_name = None


class ute_emss(ta_emss):

    def __new__(cls, *args, **kwargs):
        emss_inst = super(ute_emss, cls).__new__(cls, *args, **kwargs)
        return emss_inst
